func testWindowShouldCloseDefersForLiveInvestigateTab() {
  let store = makeStore([project("/a", workrooms: ["main"])])
  let t = target(store, "/a", "main")
  let tab = store.startInvestigate(bannerState: investigateBanner(t), target: t, cwd: t.path)
